// Validate and structure the incoming brief
const body = $input.first().json.body ?? $input.first().json;

const required = ['product', 'audience'];
for (const field of required) {
  if (!body[field]) throw new Error(`Missing required field: ${field}`);
}

const FORMULA_GUIDES = {
  'testimonial': 'Open with "I was skeptical but…". Personal story arc. Specific before/after detail. Casual language, imperfect grammar ok.',
  'problem-solution': 'Lead with the pain point in first sentence. Agitate it briefly. Introduce product as the fix. Show result.',
  'product-review': 'Unboxing feel. What you liked. One small honest complaint (builds trust). Net positive verdict.',
  'grwm': 'Routine-style narration. Product woven into daily habit. Conversational, slice-of-life tone.',
  'comparison': 'Was using X before. Tried this. Here\'s the difference. Specific contrast points.',
};

const formula = body.formula ?? 'testimonial';
if (!FORMULA_GUIDES[formula]) throw new Error(`Invalid formula: ${formula}. Use: ${Object.keys(FORMULA_GUIDES).join(', ')}`);

return [{
  json: {
    brief: {
      product: body.product,
      audience: body.audience,
      job: body.job ?? `30s UGC ad script for ${body.product}`,
      formula,
      variants: Math.min(Math.max(parseInt(body.variants ?? '3'), 1), 5),
      voiceRef: body.voiceRef ?? null,
      constraints: body.constraints ?? null,
      successCriteria: body.successCriteria ?? null,
    },
    formulaGuide: FORMULA_GUIDES[formula],
  }
}];

