// Parse Claude's response into individual scripts and score them
const response = $input.first().json;
const rawText = response.content[0].text;
const brief = $('Validate Brief').first().json.brief;

// Split on numbered markers
let scripts = rawText
  .split(/\n(?=(?:Script\s*)?\d+[.):]\s)/i)
  .map(s => s.trim())
  .filter(s => s.length > 20);

if (scripts.length < brief.variants) {
  // Fallback: double newline split
  const fallback = rawText.split(/\n{2,}/).filter(s => s.trim().length > 50);
  if (fallback.length > scripts.length) scripts = fallback;
}

// Quality scoring
const HYPE_PATTERNS = [
  /[🔥🚀💯⚡✨🎯💪]/g,
  /game.?changer/i, /revolutionary/i, /transform your life/i,
  /\bOMG\b/i, /\bAMAZING\b/i, /limited time offer/i, /act now/i,
];
const CORPORATE_PATTERNS = [
  /leverage/i, /utilize/i, /synergy/i, /cutting.?edge/i,
  /best.?in.?class/i, /industry.?leading/i, /empower/i,
];
const SPECIFIC_INDICATORS = [
  /\d+\s*(days?|weeks?|months?|lbs?|pounds?|percent|%|hours?|minutes?)/i,
  /\$\d+/, /before and after/i, /used to|used it for/i,
];

function score(script) {
  const wordCount = script.split(/\s+/).filter(Boolean).length;
  const checks = [
    wordCount >= 60 && wordCount <= 150,
    !HYPE_PATTERNS.some(p => p.test(script)),
    !CORPORATE_PATTERNS.some(p => p.test(script)),
    SPECIFIC_INDICATORS.some(p => p.test(script)),
    (script.split(/[.!?\n]/)[0] ?? '').split(/\s+/).filter(Boolean).length <= 18,
    /\b(i'm|i've|i'd|can't|don't|it's|that's|you're|didn't|wouldn't)\b/i.test(script),
  ];
  const passed = checks.filter(Boolean).length;
  return { score: Math.round((passed / checks.length) * 100), passed: passed >= 4 };
}

const scored = scripts.map((script, i) => ({
  index: i + 1,
  script,
  quality: score(script),
}));

// Pick the highest scorer
const winner = scored.reduce((best, s) =>
  s.quality.score > best.quality.score ? s : best
, scored[0]);

return [{
  json: {
    brief: $('Validate Brief').first().json.brief,
    allScripts: scored,
    winner,
  }
}];

