// Parse Claude's pipeline asset response into named fields
const response = $input.first().json;
const rawText = response.content[0].text;
const { brief, allScripts, winner } = $('Score & Pick Winner').first().json;

function extract(header, nextHeader) {
  const start = rawText.indexOf(`## ${header}`);
  if (start === -1) return '';
  const contentStart = rawText.indexOf('\n', start) + 1;
  const end = nextHeader ? rawText.indexOf(`## ${nextHeader}`) : rawText.length;
  return rawText.slice(contentStart, end === -1 ? rawText.length : end).trim();
}

const assets = {
  imagePrompt: extract('IMAGE PROMPT (Nano Banana / Flux)', 'VIDEO PROMPT'),
  videoPrompt: extract('VIDEO PROMPT (VEO / Kling)', 'VOICE SCRIPT'),
  voiceScript: extract('VOICE SCRIPT (ElevenLabs)', 'ELEVENLABS NOTES'),
  elevenLabsNotes: extract('ELEVENLABS NOTES'),
};

const timestamp = new Date().toISOString().replace(/[:.]/g, '-').slice(0, 16);
const slug = brief.product.toLowerCase().replace(/[^a-z0-9\s-]/g, '').replace(/\s+/g, '-').slice(0, 40);

return [{
  json: {
    meta: {
      timestamp,
      product: brief.product,
      formula: brief.formula,
      folderName: `${timestamp}-${slug}`,
    },
    brief,
    selectedScript: {
      text: winner.script,
      score: winner.quality.score,
      passed: winner.quality.passed,
      variantNumber: winner.index,
    },
    allScripts,
    assets,
  }
}];
